entries[181815] = { ["name"] = "Armored Bonehoof Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A favored mount of the House of the Chosen, the tauralus only gets more angry and vicious when exposed to battle.\"\nDrop:\nSabriel the Bonecleaver\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
entries[181816] = { ["name"] = "Sinful Gladiator's Sigil of Adaptation", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+28 [Agility or Strength or Intellect]\nEquip: Removes any loss of control effect with a duration of 5 seconds or more. This effect can only occur once every 1 min.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[181817] = { ["name"] = "Deathbringer's Flayedwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[181818] = { ["name"] = "Chewed Reins of the Callow Flayedwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Callow Flayedwing.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Flayedwings are a necessary force in the cycle of life for the Shadowlands, acting as both prey and predator for the harsh environment of Maldraxxus.\"\nZone:\nMaldraxxus" }
entries[181819] = { ["name"] = "Marrowfang's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Marrowfang.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Marrowfang, Bonefang's progeny, was respected by Amarth the Harvester for her insatiable appetite, even if it disrupted any experiments that the sadistic commander wanted to run.\"\nDrop:\nNalthor the Rimebinder\nZone:\nThe Necrotic Wake (Mythic)\n\nDrop:\nChallenger's Cache\nZone:\nThe Necrotic Wake" }
entries[181820] = { ["name"] = "Armored Chosen Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The tauralus has two tails, which are both absolutely necessary for whipping away buzzing pests like the bloodlouse.\"\nAchievement:\nThings To Do When You're Dead\nCategory:\nCovenant Sanctums" }
entries[181821] = { ["name"] = "Armored Plaguerot Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 39\n\n\"When fully armored, a tauralus can take an incredible amount of damage before falling, making it a valuable ally in battle.\"\nCovenant:\nNecrolord\nVendor:\nSu Zettai\nZone:\nMaldraxxus\nCost:\n3000" }
entries[181822] = { ["name"] = "Armored War-Bred Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The tauralus that serve the armies of Maldraxxus have had all traits of compassion bred out of them, and are only adorned in armor when they show that no sword or spell can stop them from carrying their rider to victory.\"\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
