entries[182074] = { ["name"] = "Chosen Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Even an unarmored tauralus is a valuable ally in battle, its enormous horns capable of piercing even plate armor.\"\nAchievement:\nThe Gang's All Here\nCategory:\nCovenant Sanctums" }
entries[182075] = { ["name"] = "Bonehoof Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"There are quite a few reasons that you do not want to stand behind a tauralus, the hooves and whip-like tails being the least of them.\"\nDrop:\nTahonta\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
entries[182076] = { ["name"] = "Plaguerot Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 23\n\n\"The tauralus is considered courageous, though scholars of Maldraxxus have long wondered if their lack of fear is simply due to the tiny size of their brains.\"\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
entries[182077] = { ["name"] = "War-Bred Tauralus", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The soldiers of Maldraxxus protect the Shadowlands, and require a mount that is both capable and calm when faced with overwhelming odds.\"\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
entries[182078] = { ["name"] = "Bonesewn Fleshroc", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only expert flesh-stitchers who have demonstrated mastery over the magics of Maldraxxus are powerful enough to construct a deathroc of this size.\"\nProfession:\nAbominable Stitching\nZone:\nMaldraxxus" }
entries[182079] = { ["name"] = "Slime-Covered Reins of the Hulking Deathroc", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Hulking Deathroc.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Deathrocs are stitched monstrosities from the discarded viscera, bone, and organs that were not required to construct soldiers for the House of Constructs.\"\nDrop:\nViolet Mistake\nZone:\nMaldraxxus" }
entries[182080] = { ["name"] = "Predatory Plagueroc", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Gieger's everlasting hunger is legendary amongst the House of Constructs, and no beast is too large or bony to fit inside its massive stomach.\"\nDrop:\nGieger\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
entries[182081] = { ["name"] = "Reins of the Colossal Slaughterclaw", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Colossal Slaughterclaw.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only the most stalwart stable masters of Maldraxxus are able to break the will of the colossal slaughterclaws, giving all champions of the Undying Army a fearsome ally in the Shadowlands.\"\nDrop:\nSupplies of the Undying Army\nZone:\nMaldraxxus" }
entries[182082] = { ["name"] = "Lurid Bloodtusk", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Undying Army\n- Exalted\n\n\"Only bloodtusks that survive the Contest of Conquest are deemed worthy enough to become a mount of the Undying Army.\"\nVendor:\nNalcorn Talsen\nZone:\nMaldraxxus\nFaction:\nThe Undying Army - Exalted\nCost:" }
entries[182083] = { ["name"] = "Bonecleaver's Skullboar", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Sabreil was known for the ruthless efficiency with which she dismembered foes, feeding their bones to her loyal skullboar.\"\nVendor:\nCollector Ta'Steld\nZone:\nOribos\nCost:\n5000" }
entries[182084] = { ["name"] = "Gorespine", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Nerissa trampled over countless bodies on the back of Gorespine as she rose to prominence as the commander of the Lichsworn forces for the House of Rituals.\"\nDrop:\nNerissa Heartless\nZone:\nMaldraxxus" }
entries[182085] = { ["name"] = "Blisterback Bloodtusk", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The House of the Chosen train their mounts in all manner of difficult circumstances, so that no matter the battle, they will never falter.\"\nDrop:\nWarbringer Mal'korak\nZone:\nMaldraxxus" }
