entries[182451] = { ["name"] = "Glimmerdust's Grand Design", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+15 Intellect\nUse: Mark a friendly player with Glimmering Dust, healing them for [ 14 * (1 + Versatility)] every 3.0 sec for 2 min. If they fall below 35% health, Glimmering Dust is consumed to grant them a shield that prevents [(1 + Versatility) * 1828 ] damage for 15 sec. (2 Min Cooldown)\nSell Price:" }
