entries[182589] = { ["name"] = "Loyal Gorger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Crawling forth from the cracks between the realms, the devourers have a voracious appetite for anima. Little is known of their origins, but all denizens of the Shadowlands see their recent boldness as a sign of the end times.\"\nQuest:\nA New Pack" }
entries[182590] = { ["name"] = "Vinewormed Coin Pouch", ["text"] = "Binds when picked up\n\"Coins jingle, nearly falling out of the many holes.\"\n<Right Click to Open>" }
entries[182591] = { ["name"] = "Vinecovered Infused Rubies", ["text"] = "Binds when picked up\n\"If you can pull them out of the vines, the dredgers are always willing to trade for Infused Rubies.\"\n<Right Click to Open>" }
entries[182592] = { ["name"] = "Infused Endmire Fruit", ["text"] = "Binds when picked up\nUse: Restores ( 22500 / 5 * 20) health and ( 30000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 80 Critical Strike for 1 hour.\n\"Once much like a pear, the endmire has twisted it and the devourer mites flourish on it.\"\nSell Price:" }
entries[182593] = { ["name"] = "Sinrunner Carving", ["text"] = "Binds when picked up\nSell Price:" }
entries[182594] = { ["name"] = "A Sparkling Ruby Necklace", ["text"] = "Binds when picked up\nSell Price:" }
entries[182595] = { ["name"] = "Sturdy Horseshoe", ["text"] = "Binds when picked up\n\"Protective footwear for horse-like creatures.\"" }
entries[182596] = { ["name"] = "Rampart Screecher", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Roosting among the ramparts of Castle Nathria, these giant dredbats act as sentinels and are trained to take down threats approaching the castle from the air.\"\nAchievement:\nGlory of the Nathria RaiderCategory:\nDungeons & Raids" }
entries[182597] = { ["name"] = "Comfortable Saddle Blanket", ["text"] = "Binds when picked up\n\"A soft and comfortable blanket for regulating body temperature.\"" }
entries[182598] = { ["name"] = "Demon Muzzle", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nWhen Sigil of Silence's effect ends, affected enemies deal 5.0% reduced magic damage to you for 8 sec." }
entries[182599] = { ["name"] = "Bucket of Clean Water", ["text"] = "Binds when picked up\n\"Guaranteed to quench the greatest thirst.\"" }
entries[182600] = { ["name"] = "Gormling in a Bag", ["text"] = "Quest Item\nUnique\nUse: Get ready to toss a gormling! (8 Sec Cooldown)" }
entries[182601] = { ["name"] = "Sludgefist's Head", ["text"] = "Quest Item\n\"A head taken from Sludgefist in Castle Nathria on Normal Difficulty.\"" }
entries[182602] = { ["name"] = "Sludgefist's Head", ["text"] = "Quest Item\n\"A head taken from Sludgefist in Castle Nathria on Heroic Difficulty.\"" }
entries[182603] = { ["name"] = "Sludgefist's Head", ["text"] = "Quest Item\n\"A head taken from Sludgefist in Castle Nathria on Mythic Difficulty.\"" }
entries[182604] = { ["name"] = "Roaring Fire", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nFel Devastation heals you for up to 30% more, based on your missing health." }
entries[182605] = { ["name"] = "Tactical Retreat", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nDisengage slows nearby enemy movement speed by 20.0% for 3 sec." }
entries[182606] = { ["name"] = "Bloodlouse Larva", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[182607] = { ["name"] = "Hairy Egg", ["text"] = "Binds when picked up\nUnique\nDuration: 3 days (real time)\n\"The chirps of whatever's inside grow louder. This egg is hatching into something.\"" }
entries[182608] = { ["name"] = "Virtuous Command", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nJudgment grants you Virtuous Command for 5 sec, which causes your Templar's Verdict, Crusader Strike, Blade of Justice, and auto attacks to deal 8.0% additional Holy damage." }
entries[182609] = { ["name"] = "Overdue Scroll", ["text"] = "Quest Item\n\"The House of Rituals takes late penalties seriously.\"" }
entries[182610] = { ["name"] = "Ferocious Appetite", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nKill Command critical hits reduce the cooldown of Aspect of the Wild by 1.0 sec ." }
entries[182611] = { ["name"] = "Fae Flute", ["text"] = "Quest Item\nUnique\nUse: Play the pipes to draw a gormling out of its burrow! (4 Sec Cooldown)" }
entries[182612] = { ["name"] = "The Count's Pendant", ["text"] = "Binds when picked up\nUse: Teaches you how to summon The Count.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[182613] = { ["name"] = "Refilling Inkwell", ["text"] = "Binds when picked up\nUse: Teaches you how to summon the Lost Quill.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[182614] = { ["name"] = "Blanchy's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Sinrunner Blanchy.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"In life, Blanchy appeared to be an affectionate, well-behaved horse of excellent disposition and appetite. What evils must she have committed in secret to have earned her place among the condemned souls of Revendreth?\"\nNPC:\nDead Blanchy\nLocation:\nRevendreth" }
entries[182615] = { ["name"] = "Errant Tome", ["text"] = "Quest Item\n\"An enchanted book run amok.\"" }
entries[182616] = { ["name"] = "Mischievous Quill", ["text"] = "Quest Item\n\"A magical pen that has escaped the bonds of its enchantment.\"" }
entries[182617] = { ["name"] = "Memory of Death's Embrace", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeath's Embrace Runecarving Power\nIncreases the duration of Anti-Magic Shell by 140% and any damage it absorbs heals you.\nRunecarve on: Wrist, Finger\nSource: Dungeon Drop: Kul'tharok\nRequires: Death Knight" }
entries[182618] = { ["name"] = "Reclaimed Vessel", ["text"] = "Binds when picked up\nThis Item Begins a Quest" }
entries[182619] = { ["name"] = "Looted Animacone", ["text"] = "Quest Item\n\"Glows with a soft bluish-white light.\"" }
entries[182620] = { ["name"] = "Empty Water Bucket", ["text"] = "Binds when picked up\nUnique\nUse: Fill only with clean water from Bastion or Ardenweald." }
entries[182621] = { ["name"] = "One With the Beast", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nBestial Wrath increases all damage you and your pet deal by an additional 1.0% ." }
entries[182622] = { ["name"] = "Resplendent Light", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nHoly Light heals up to 5 targets within 8 yds for 4.0% of its healing." }
entries[182623] = { ["name"] = "Soul Mirror", ["text"] = "Quest Item\nUse: Channel on a Path of Ascension capture target, containing a memory of them within the Soul Mirror to be trained against." }
entries[182624] = { ["name"] = "Show of Force", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nRevenge increases the damage of your next Thunder Clap by 12.0% . (500ms cooldown)" }
entries[182625] = { ["name"] = "Memory of an Everlasting Grip", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nGrip of the Everlasting Runecarving Power\nDeath Grip's cooldown is reduced by 3 sec and for 3 sec after casting Death Grip, you may cast the spell a second time without regard for its cooldown.\nRunecarve on: Waist, Feet\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Death Knight" }
entries[182626] = { ["name"] = "Memory of the Phearomones", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPhearomones Runecarving Power\nYou and your minions gain [ Blood : 10% /\n\nFrost, Unholy\n15% ] Haste while you are inside your Death and Decay and enemies damaged by your Death and Decay have a chance to cower in place for 3 sec.\nRunecarve on: Head, Neck, Shoulder\nSource: Quest: The Great Vault\nRequires: Death Knight" }
entries[182627] = { ["name"] = "Memory of Superstrain", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSuperstrain Runecarving Power\nYour Frost Fever, Blood Plague, and Virulent Plague also apply the other two diseases at reduced effectiveness.\nRunecarve on: Neck, Chest\nSource: Raid Drop: Stone Legion Generals\nRequires: Death Knight" }
entries[182628] = { ["name"] = "Memory of Bryndaor", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBryndaor's Might Runecarving Power\nDeath Strike refunds 15% of Runic Power spent if it heals you for more than 10% of your maximum health.\nRunecarve on: Feet, Back\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Death Knight (Blood)" }
entries[182629] = { ["name"] = "Memory of the Crimson Runes", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCrimson Rune Weapon Runecarving Power\nDancing Rune Weapon generates 5 Bone Shield charges. When a charge of Bone Shield is consumed, the cooldown of Dancing Rune Weapon is reduced by 5 sec. Additionally, when Dancing Rune Weapon fades, your Rune regeneration rate is increased by 40% for 10 sec.\nRunecarve on: Shoulder, Waist, Hands\nSource: Dungeon Drop: Halkias, the Sin-Stained Goliath\nRequires: Death Knight (Blood)" }
entries[182630] = { ["name"] = "Memory of Gorefiend's Domination", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nGorefiend's Domination Runecarving Power\nVampiric Blood generates 45 Runic Power. Additionally, Heart Strike reduces the remaining cooldown on Vampiric Blood by 2 seconds.\nRunecarve on: Legs, Feet\nSource: Raid Drop: Hungering Destroyer\nRequires: Death Knight (Blood)" }
entries[182631] = { ["name"] = "Memory of a Vampiric Aura", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nVampiric Aura Runecarving Power\nVampiric Blood grants you 5% Leech and its duration is increased by 3 sec. Additionally, your Vampiric Blood affects all party members for 50% of the effect it has on you.\nRunecarve on: Chest, Finger\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Death Knight (Blood)" }
entries[182632] = { ["name"] = "Memory of Absolute Zero", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nAbsolute Zero Runecarving Power\nFrostwyrm's Fury has 50% reduced cooldown and Freezes all enemies hit for 3 sec.\nRunecarve on: Neck, Wrist\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Death Knight (Frost)" }
entries[182633] = { ["name"] = "Memory of the Biting Cold", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBiting Cold Runecarving Power\nRemorseless Winter damage is increased by 30%. The first time Remorseless Winter deals damage to 3 different enemies, you gain Rime.\nRunecarve on: Head, Waist\nSource: Dungeon Drop: Nalthor the Rimebinder\nRequires: Death Knight (Frost)" }
entries[182634] = { ["name"] = "Memory of a Frozen Champion's Rage", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRage of the Frozen Champion Runecarving Power\nObliterate has a 15% increased chance to trigger Rime and Howling Blast generates 12 Runic Power while Rime is active.\nRunecarve on: Wrist, Hands, Finger\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Death Knight (Frost)" }
entries[182635] = { ["name"] = "Memory of Koltira", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nKoltira's Favor Runecarving Power\nObliterate deals 10% increased damage and has a 12% chance to refund 2 runes. (Proc chance: 12%, 700ms cooldown)\nRunecarve on: Shoulder, Finger\nSource: Raid Drop: Sludgefist\nRequires: Death Knight (Frost)" }
entries[182636] = { ["name"] = "Memory of the Deadliest Coil", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeadliest Coil Runecarving Power\nReduces the Runic Power cost of Death Coil by 10 and Death Coil increases the duration of Dark Transformation by 1 sec.\nRunecarve on: Chest, Back\nSource: Raid Drop: Sire Denathrius\nRequires: Death Knight (Unholy)" }
entries[182637] = { ["name"] = "Memory of Death's Certainty", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeath's Certainty Runecarving Power\nDeath Strike and Death Coil deal 35% increased damage and reduce the remaining cooldown of [ Defile ] Death and Decay by 2.0 sec.\nRunecarve on: Head, Neck, Hands\nSource: Dungeon Drop: Margrave Stradama\nRequires: Death Knight (Unholy)" }
entries[182638] = { ["name"] = "Memory of a Frenzied Monstrosity", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFrenzied Monstrosity Runecarving Power\nDark Transformation also increases the attack speed and damage of you and your Monstrosity by 12%.\nRunecarve on: Legs, Back\nSource: World Boss Drop: Nurgash Muckformed\nRequires: Death Knight (Unholy)" }
entries[182639] = { ["name"] = "Gilded Skull Key", ["text"] = "Quest Item\n\"Unlocks the gate to Kivarr's cage.\"" }
entries[182640] = { ["name"] = "Memory of a Reanimated Shambler", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nReanimated Shambler Runecarving Power Approximately 1.75 procs per minute\nYour attacks have a chance to summon a Super Zombie that shambles forward and explodes, dealing [ Unholy : [(114.4 / 100 * (157.5% of Attack Power))] /\n\nBlood, Frost\n(157.5% of Attack Power) ] Shadow damage and applying a Festering Wound to all nearby enemies. Deals reduced damage beyond 8 targets.\nRunecarve on: Waist, Legs\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Death Knight (Unholy)" }
entries[182641] = { ["name"] = "Lustrous Silver Key", ["text"] = "Quest Item\n\"Unlocks the gate to Kivarr's cage.\"" }
entries[182642] = { ["name"] = "Winged Arcanum", ["text"] = "Quest Item\n\"A treatise on the magic of Bastion and the kyrian.\"" }
entries[182643] = { ["name"] = "Paths of the First Ones", ["text"] = "Quest Item\n\"An eldritch tome, rife with speculation about the precursors to the rulers of the Shadowlands.\"" }
entries[182644] = { ["name"] = "Greater Wards and Barriers, Volume IV", ["text"] = "Quest Item\n\"A pedantic volume of spells and counterspells.\"" }
entries[182645] = { ["name"] = "Binding of the Banished One", ["text"] = "Quest Item\n\"An ancient, dusty tome describing the trials of a figure known as \"The Banished One.\"\"" }
entries[182646] = { ["name"] = "Repeat Decree", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nElysian Decree echoes a second sigil 1 second later for 15.0% damage." }
entries[182647] = { ["name"] = "Runestone Spike", ["text"] = "Quest Item\n\"The stone was found in the chest of an unfortunate possessed fae.\"\nSell Price:" }
entries[182648] = { ["name"] = "Sharpshooter's Focus", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nTrueshot lasts 20.0% longer." }
entries[182649] = { ["name"] = "Brutal Projectiles", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nYour auto attacks have a 10% chance to cause your next Rapid Fire to deal 3.0% increased damage for each shot." }
entries[182650] = { ["name"] = "Arboreal Gulper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The wood and foliage growing atop this toad is a natural part of its body, helping it siphon anima from the air to nourish itself.\"\nDrop:\nHumon'gozz\nZone:\nArdenweald" }
entries[182651] = { ["name"] = "Destructive Reverberations", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nAncient Aftershock's cooldown is reduced by 15 sec, and its damage is increased by 4% ." }
entries[182652] = { ["name"] = "Larion Tamer's Harness" }
entries[182653] = { ["name"] = "Larion Treats", ["text"] = "Use: Befriend a larion, causing them to assist you for 10 min. (5 Sec Cooldown)\nSell Price:" }
entries[182654] = { ["name"] = "Bonescript Dispatches", ["text"] = "Binds when picked up\n\"The movements of the Maldraxxi invaders would be of great important to Malcorn Caliga at the Theater of Pain in Maldraxxus.\"\nSell Price:" }
entries[182655] = { ["name"] = "Hill King's Roarbox", ["text"] = "Binds when picked up\nUnique\nUse: Send out a fierce roar, attracting enemies within 40 yards. Ineffective on targets not native to the Shadowlands. (2 Min Cooldown)\n\"Alert all would be challengers of your dominance.\"" }
entries[182656] = { ["name"] = "Disturb the Peace", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\n[ Protection : Shockwave's /\n\nArms, Fury\nPiercing Howl's ] cooldown is reduced by 5 sec ." }
entries[182657] = { ["name"] = "Deadly Chain", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nTrick Shots secondary damage is increased by 5.0% ." }
entries[182658] = { ["name"] = "Mantle of Eternal Victory", ["text"] = "Quest Item\n\"Once a part of the Primus' armor, this mantle is still filled with power.\"" }
entries[182659] = { ["name"] = "Night Lilly", ["text"] = "Quest Item\n\"The strong scent has an intense calming quality.\"" }
entries[182660] = { ["name"] = "Recipe: Shadestone", ["text"] = "Binds when picked up\nUse: Teaches you how to transmute Shadestone.\nRequires Shadowlands Alchemy (170)\nRequires Honored with The Avowed.\nSell Price:\nShadestone\nCrafting Reagent\n\"Created by players with the Alchemy skill. Can be bought and sold on the auction house.\"\nSell Price:\nRequires Ground Death Blossom (5), Ground Vigil's Torch (2), Ground Widowbloom (2), Ground Marrowroot (2), Ground Rising Glory (2)" }
entries[182661] = { ["name"] = "Fun Guss", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nRequires Marasmius\n- Friendly" }
entries[182662] = { ["name"] = "Leafadore", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nParticipate in three different performances at the Star Lake Amphitheater and be a member of the Night Fae Covenant." }
entries[182663] = { ["name"] = "Trootie", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nRequires Renown 27" }
entries[182664] = { ["name"] = "Stemmins", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nRequires Court of Night\n- Friendly\nYou must be a member of the Night Fae Covenant." }
entries[182665] = { ["name"] = "Recipe: Sins to Virtue", ["text"] = "Binds when picked up\nUse: Teaches you how to transmute Sins to Virtue.\nRequires Shadowlands Alchemy (150)\nSell Price:\nShaded Bag of Ore\nBinds when picked up\n\"A bag of ore from the Shadowlands.\"\n<Right Click to Open>\nRequires Porous Stone (4), Shaded Stone (2)" }
entries[182666] = { ["name"] = "Formula: Enchanted Elethium Bar", ["text"] = "Binds when picked up\nUse: Teaches you how to craft an Enchanted Elethium Bar.\nRequires Shadowlands Enchanting (115)\nSell Price:\nEnchanted Elethium Bar\nCrafting Reagent\n\"Created by players with the Enchanting skill.\"\nSell Price:\nRequires Soul Dust , Elethium Ore (2)" }
entries[182667] = { ["name"] = "Focused Light", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nHoly Shock's critical effect chance is increased by 5.0% ." }
entries[182668] = { ["name"] = "Recipe: Feast of Gluttonous Hedonism", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Feast of Gluttonous Hedonism.\nRequires Shadowlands Cooking (75)\nRequires Court of Harvesters\n- Revered\nSell Price:\nFeast of Gluttonous Hedonism\nUse: Set out a Feast of Gluttonous Hedonism to feed up to 35 people in your raid or party!\n\nRestores 173077 health and 138461 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 53 in a stat for 1 hour.\nSell Price:\nRequires Spinefin Piranha (10), Silvergill Pike (10), Tenebrous Ribs (10), Phantasmal Haunch (10), Elysian Thade (5), Smuggled Azerothian Produce (5), Rich Grazer Milk (5), Lusterwheat Flour (5)" }
entries[182669] = { ["name"] = "Pattern: Loosened Belt", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Loosened Belt.\nRequires Shadowlands Leatherworking (50)\nSell Price:\nLoosened Belt\nOptional Crafting Reagent\n\nProvides the following property: Well Fed lasts longer\n\"An Optional Reagent that can be crafted into a piece of armor, increasing the duration of Well Fed effects.\"\nSell Price:\nRequires Desolate Leather (20), Pallid Bone (20)" }
entries[182670] = { ["name"] = "Plans: Reinforced Girdle", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Reinforced Girdle.\nCreate an Reinforced Girdle, an Optional Reagent that can be crafted into a piece of armor, allowing the wearer to retain their Well Fed buff when slain in an Arena or Battleground.\nRequires Shadowlands Blacksmithing (50)\nSell Price:\nReinforced Girdle\nOptional Crafting Reagent\n\nProvides the following property: Retain Well Fed when slain in Arena or Battleground\n\"An Optional Reagent that can be crafted into a piece of armor, allowing the wearer to retain their Well Fed buff when slain in an Arena or Battleground.\"\nSell Price:\nRequires Laestrite Ore (13), Luminous Flux (2)" }
entries[182671] = { ["name"] = "Runelight Leaper", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[182672] = { ["name"] = "Misty Leaper", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[182673] = { ["name"] = "Shimmerbough Hoarder", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[182674] = { ["name"] = "Sir Reginald", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nRequires Marasmius\n- Friendly" }
entries[182675] = { ["name"] = "Untempered Dedication", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nLight of the Martyr's damage and healing is increased by 5.0% each time it is cast. This effect can stack up to 5 times and lasts for 15 sec." }
entries[182676] = { ["name"] = "Veilwing's Heart", ["text"] = "Quest Item\n\"A source of great magical power, particularly useful in necromantic rituals.\"" }
entries[182677] = { ["name"] = "Punish the Guilty", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nShield of the Righteous deals 15% more damage to targets affected by Judgment." }
entries[182678] = { ["name"] = "Intact Spore Cluster", ["text"] = "Quest Item\n\"Often burned as incense to aid in concentration during intense rituals.\"" }
entries[182679] = { ["name"] = "Bundle of Reagents", ["text"] = "Quest Item\n\"Contains various supplies for Kel'Thuzad's ritual.\"" }
entries[182680] = { ["name"] = "9.0 Monster - Beastwarrens - Vignette Vasanok - Weapon - LJS", ["text"] = "Binds when picked up\nOne-Hand Mace\n1 Damage Speed 3.60\n(0.3 damage per second)\nSell Price:" }
entries[182681] = { ["name"] = "Vengeful Shock", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nAvenger's Shield causes your target to take 3.0% increased Holy damage from you for 5 sec." }
