entries[182954] = { ["name"] = "Inquisition Gargon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires you to be a part of the Venthyr Covenant and Exalted with The Avowed.\n\n\"The gargon of the Inquisitors are some of the most vicious ever carved. The Avowed seek to recapture these beasts and return them to the righteous duty of assisting in the purifying of souls rather than the perversions performed at the hands of the Inquisitors.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
